/* Digital society — Paper 1 bank (original questions written to the IB DS guide, first assessment 2024).
   Structured questions: (a) AO1 [6], (b) AO2 [6], (c) AO3 [8] with markbands.
   t = content topics, x = contexts, k = concepts (shown as tags). */
const P1Q=[
{id:"face-school",title:"Facial recognition in schools",t:["3.6","3.1"],x:["4.5","4.6"],
stem:`<p>A secondary school has installed cameras with facial recognition software at its entrances. The system records when each student arrives and leaves, and automatically sends a message to parents if a student is absent.</p><p>The school says the system saves teachers 15 minutes every morning that was previously spent taking attendance by hand. Some parents have raised concerns about how the images of their children are stored and who can access them.</p>`,
a:[{q:"Identify two types of data collected by the facial recognition system.",m:2,ms:["Images/video of students' faces","biometric data/facial features/face template","time/date of arrival and departure","location (which entrance)","student identity/name/ID number","attendance/absence records"],note:"Award [1] for each type of data identified up to [2]."},
   {q:"Identify two characteristics of biometric data.",m:2,ms:["Unique to each individual","physical/biological characteristic","difficult to change/permanent","can be measured/converted into digital form","personally identifiable/sensitive","difficult to forge/fake"],note:"Award [1] for each characteristic up to [2]."},
   {q:"Describe how machine learning allows the system to recognize a student's face.",m:2,ms:["The system is trained using many labelled images of each student's face","it learns patterns/features (e.g. distance between eyes) so it can match a new image to a stored face/identity"],note:"Award [1] for each part of the description up to [2]."}],
b:[{q:"Explain one reason why the system may wrongly identify a student.",m:2,ms:["Poor lighting/camera angle/face partly covered (masks, hats)","so the features captured do not match the stored template","Training data may not represent all groups equally (bias)","so accuracy is lower for some students (e.g. darker skin tones, twins)","The student's appearance changes over time (growth, glasses, haircut)","so the stored template becomes out of date"],note:"Award [1] for a reason and [1] for its development up to [2]."},
   {q:"Explain two measures the school could take to protect the privacy of the students' data.",m:4,ms:["Encrypt the stored images/biometric templates","so they cannot be read if the system is hacked","Limit access to authorised staff only (role-based access/passwords)","so fewer people can view or misuse the data","Store templates rather than full images/delete images after processing","reducing what could be leaked","Set a data retention policy and delete data when students leave","so data is not kept longer than needed","Obtain informed consent/allow parents to opt out","so families control how their children's data is used"],note:"Award [1] for a measure and [1] for its development. Mark as [2] + [2]."}],
c:{q:"To what extent is it acceptable for schools to use facial recognition technology to monitor students?",
ind:["Acceptable: saves teacher time and improves accuracy of attendance (systems)","acceptable: improves safety — knows who is on site in an emergency, detects intruders (power, systems)","acceptable: parents are informed quickly of absences (change, values)","acceptable if data is encrypted, access limited, consent obtained and data deleted when no longer needed (ethics, values)","Not acceptable: biometric data of minors is highly sensitive and cannot be changed if leaked (ethics, values)","not acceptable: surveillance culture/normalising constant monitoring; affects trust and student identity (identity, power, space)","not acceptable: bias/misidentification may unfairly mark some students absent (ethics)","not acceptable: data may be shared with third parties/used for other purposes (function creep) (power, values)","alternatives exist (ID cards, manual registers) that are less intrusive","a reasoned conclusion, e.g. acceptable only with strict safeguards and consent"],
kw:"Change, identity, power, space, systems, values and ethics, surveillance, biometric data, privacy, consent, algorithmic bias, accountability."}},

{id:"scooters",title:"Shared e-scooters in cities",t:["3.4","3.1","3.7"],x:["4.3","4.2"],
stem:`<p>A company provides shared electric scooters (e-scooters) in a city. Users find a scooter using a smartphone app, unlock it by scanning a QR code and pay per minute of use. When the trip ends, the scooter can be left anywhere inside a zone marked on the app's map.</p><p>Each scooter has a GPS receiver and a SIM card that sends data to the company's servers every 30 seconds.</p>`,
a:[{q:"Identify two items of data the scooter could send to the company's servers.",m:2,ms:["Location/GPS coordinates","battery level","speed","whether it is locked/in use","user/trip ID","distance travelled","time/duration of trip","faults/error codes","tilt/fallen over"],note:"Award [1] for each item up to [2]."},
   {q:"Identify two types of network used by the e-scooter system.",m:2,ms:["Mobile/cellular network (4G/5G via the SIM card)","the internet/WAN","wireless network/Wi-Fi","Bluetooth/PAN (phone to scooter)","cloud network/client–server"],note:"Award [1] for each type up to [2]."},
   {q:"Describe how a QR code is used to unlock a scooter.",m:2,ms:["The app uses the phone camera to read the QR code, which contains the scooter's unique ID","the ID is sent to the server, which checks the user's account/payment and sends an unlock command to that scooter"],note:"Award [1] for each part of the description up to [2]."}],
b:[{q:"Explain one way in which the company could use the location data to improve its service.",m:2,ms:["Identify areas/times of high demand (data analytics/heat maps)","so more scooters can be placed there","Find scooters with low battery","so staff can collect and charge them efficiently","Detect scooters left outside the zone","so they can be moved/users charged"],note:"Award [1] for a way and [1] for its development up to [2]."},
   {q:"Explain two concerns that city residents may have about the e-scooter scheme.",m:4,ms:["Scooters left on pavements","create obstacles for pedestrians, especially people with disabilities or prams","Safety of riders and pedestrians","accidents/injuries from speed or inexperienced riders","Privacy","detailed records of users' journeys could reveal where they live/work","Environmental impact","batteries and short scooter life create e-waste; vans collecting scooters cause emissions"],note:"Award [1] for each concern and [1] for its development. Mark as [2] + [2]."}],
c:{q:"Evaluate the opportunities and challenges for a city of allowing shared e-scooter schemes.",
ind:["Opportunities: low-emission alternative to short car journeys, reducing congestion and pollution (change, space, systems)","convenient 'last mile' link to public transport","data on journeys can help city planners design cycle lanes (systems, power)","new jobs and business; affordable transport for people without cars","Challenges: clutter and accessibility problems on pavements (space, values)","safety and injuries; unclear rules on helmets/speed (ethics)","privacy of location data; who owns and can sell the data (power, values)","environmental cost of batteries, manufacturing and collection vans","excludes people without smartphones/bank cards (digital divide)","need for regulation (parking zones, speed limits by geofencing)","a reasoned conclusion weighing opportunities and challenges"],
kw:"Change, power, space, systems, values and ethics, IoT, GPS, location data, networks, sustainability, digital divide."}},

{id:"learning-analytics",title:"Learning analytics on an online platform",t:["3.1","3.2"],x:["4.5"],
stem:`<p>A school uses an online learning platform for homework. The platform records how long each student spends on each task, the number of attempts and their scores.</p><p>An algorithm uses this data to place students into "on track", "at risk" or "ahead" groups and shows the results to teachers on a dashboard (see Figure 1).</p>
<p><b>Figure 1: Teacher dashboard (extract)</b></p>
<table class="dt"><tr><th>Student</th><th>Average time per task</th><th>Average score</th><th>Status</th></tr><tr><td>Student 1</td><td>12 min</td><td>78%</td><td>On track</td></tr><tr><td>Student 2</td><td>3 min</td><td>41%</td><td>At risk</td></tr><tr><td>Student 3</td><td>25 min</td><td>52%</td><td>At risk</td></tr><tr><td>Student 4</td><td>9 min</td><td>95%</td><td>Ahead</td></tr></table>`,
a:[{q:"Identify two items of quantitative data shown in Figure 1.",m:2,ms:["Average time per task","average score"],note:"Award [1] for each item up to [2]. Do not accept status (it is categorical/qualitative)."},
   {q:"Identify two characteristics of an algorithm.",m:2,ms:["Unambiguous","finite","well-defined inputs","well-defined outputs","feasible","sequence of steps/instructions"],note:"Award [1] for each characteristic up to [2]."},
   {q:"Identify two other ways, apart from a table, of representing the data in Figure 1.",m:2,ms:["Bar chart/graph","pie chart","line graph/trend over time","scatter graph","infographic","heat map/colour coding","report"],note:"Award [1] for each way up to [2]."}],
b:[{q:"Explain one reason why the algorithm may have placed Student 3 in the \"at risk\" group even though the student spends the most time on tasks.",m:2,ms:["The algorithm may give more weight to the score than to time","so a low average score (52%) results in 'at risk' despite effort","Spending a long time may be interpreted as struggling","so long time combined with a modest score triggers 'at risk'"],note:"Award [1] for a reason and [1] for its development up to [2]."},
   {q:"Explain two limitations of using this data to judge how well a student is learning.",m:4,ms:["Time on task does not show what the student was doing","the student may have left the page open/been distracted, or got help","Scores may not reflect understanding","students may guess, copy or use AI tools","The data ignores learning outside the platform","e.g. reading, practical work, class discussion","Students with poor internet access/shared devices may score lower","so the data reflects the digital divide rather than ability"],note:"Award [1] for each limitation and [1] for its development. Mark as [2] + [2]."}],
c:{q:"Discuss whether teachers should rely on learning analytics algorithms to decide which students need extra support.",
ind:["For: identifies patterns quickly across large classes that teachers might miss (systems)","early intervention before students fall behind (change)","consistent and based on data rather than impressions/teacher bias (values)","saves teacher time for teaching","Against: data is incomplete — does not capture well-being, home circumstances, effort offline","algorithmic bias and black-box decisions; teachers may not know how status is calculated (power, ethics)","labelling students 'at risk' can affect motivation and identity (identity)","erosion of professional/human judgement (values)","privacy of detailed behavioural data; who else sees it","conclusion: useful as one input, with teachers making final decisions"],
kw:"Change, identity, power, systems, values and ethics, data analytics, algorithmic bias, transparency, human judgement."}},

{id:"teen-feeds",title:"Recommendation algorithms and young people",t:["3.2","3.5"],x:["4.4","4.7"],
stem:`<p>A video-sharing app shows each user an endless feed of short videos. The app's recommendation algorithm learns from what users watch, like, share and skip, and shows more of the type of content that keeps them watching.</p><p>A survey of 15–17 year olds found that many spend more than three hours a day on the app, and some say it makes them feel worse about their appearance.</p>`,
a:[{q:"Identify two items of data the app could use to recommend videos.",m:2,ms:["Watch time/how long a video is watched","likes","shares","comments","videos skipped","search history","accounts followed","location","time of day/device","age/profile information"],note:"Award [1] for each item up to [2]."},
   {q:"Identify two types of digital media that users may share on the app.",m:2,ms:["Video","audio/music","images/photos","text/captions/comments","hashtags","memes","live streams","animations","user-generated content"],note:"Award [1] for each type up to [2]."},
   {q:"Describe what is meant by a \"filter bubble\".",m:2,ms:["A situation where an algorithm shows users only content similar to what they already like/agree with","so they are rarely exposed to different views/content, reinforcing existing interests or beliefs"],note:"Award [1] for each part of the description up to [2]."}],
b:[{q:"Explain one reason why the app's design may make it difficult for users to stop watching.",m:2,ms:["The feed is endless/autoplays the next video","so there is no natural stopping point","Content is personalised to be highly engaging","so users keep getting rewards (dopamine) and continue scrolling","Notifications/streaks","encourage users to return frequently"],note:"Award [1] for a reason and [1] for its development up to [2]."},
   {q:"Explain two features the app could introduce to support the well-being of younger users.",m:4,ms:["Daily time limits/screen-time reminders","which prompt users to take breaks","Turn off autoplay/endless scroll by default for under-18s","so users must choose to continue","Reduce recommendations of appearance/diet content for teens","limiting harmful comparisons","Option to reset or choose topics for the feed","so users can escape filter bubbles","Hide like counts","reducing social comparison and pressure"],note:"Award [1] for each feature and [1] for its development. Mark as [2] + [2]."}],
c:{q:"To what extent should social media companies be held responsible for the effects of their recommendation algorithms on young people's mental health?",
ind:["Responsible: companies design algorithms to maximise engagement and profit (power, values)","they hold the data and know the effects but are not transparent (black-box algorithms)","young people may not have the maturity to self-regulate","companies can easily change defaults (time limits, safer feeds)","Shared responsibility: parents, schools, users and governments also play a role","research on causation is mixed — other factors affect mental health","platforms also bring benefits: connection, creativity, support communities (expression, identity)","regulation (age verification, duty of care laws) vs freedom of expression","a reasoned conclusion on the degree of responsibility"],
kw:"Change, expression, identity, power, systems, values and ethics, algorithms, filter bubbles, addiction, accountability, transparency."}},

{id:"gig-work",title:"Algorithmic management of delivery riders",t:["3.2","3.6"],x:["4.2"],
stem:`<p>A food-delivery platform uses an app to assign orders to self-employed riders. An algorithm decides which rider receives each order, calculates the payment for each delivery, and gives every rider a rating based on speed, customer feedback and how often they accept orders.</p><p>Riders with low ratings receive fewer orders. Riders cannot see exactly how their rating is calculated.</p>`,
a:[{q:"Identify two inputs the algorithm could use to choose which rider receives an order.",m:2,ms:["Rider's distance from the restaurant/location","rider's rating","rider's availability/online status","type of vehicle","traffic conditions","estimated delivery time","number of orders already carried"],note:"Award [1] for each input up to [2]."},
   {q:"Identify two characteristics of the gig economy.",m:2,ms:["Short-term/task-based work","workers are self-employed/independent contractors","flexible hours","work allocated through a digital platform/app","paid per task","few employment benefits (sick pay, holidays)"],note:"Award [1] for each characteristic up to [2]."},
   {q:"Describe what is meant by a \"black box\" algorithm.",m:2,ms:["An algorithm whose internal workings/how it reaches decisions cannot be seen or understood by users (or sometimes even developers)","so people affected cannot check or challenge its decisions"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one advantage for the platform of using an algorithm to assign orders.",m:2,ms:["Decisions are made instantly for thousands of orders","so deliveries are faster and customers are happier","No need to employ many human dispatchers","reducing costs"],note:"Award [1] for an advantage and [1] for its development up to [2]."},
   {q:"Explain two ways in which the rating system could be unfair to riders.",m:4,ms:["Customer feedback may be biased","e.g. low ratings for late food caused by the restaurant, or discrimination","Penalising riders for rejecting orders","forces riders to accept unsafe/unprofitable jobs","Riders cannot see how ratings are calculated","so they cannot challenge mistakes or improve","Factors outside riders' control (weather, traffic)","lower their speed scores"],note:"Award [1] for each way and [1] for its development. Mark as [2] + [2]."}],
c:{q:"Evaluate the use of algorithms to manage workers in the gig economy.",
ind:["Positives: efficient matching of supply and demand; flexible work available on demand (systems)","workers can choose when to work; low barriers to entry (change, values)","consistent rules applied to everyone","Negatives: lack of transparency and accountability for decisions (power)","workers' income and access to work controlled by an opaque algorithm (power, values)","pressure to work fast may compromise safety","bias in ratings and allocation (ethics)","loss of human management, no one to appeal to","Regulation/interventions: right to explanation, worker unions, minimum pay rules","a reasoned conclusion"],
kw:"Change, power, systems, values and ethics, algorithmic accountability, transparency, bias, automation, employment and labour."}},

{id:"voice-assistant",title:"Voice assistants in the home",t:["3.6","3.7","3.4"],x:["4.1"],
stem:`<p>A family uses a smart speaker with a voice assistant. They ask it to play music, set reminders and control smart lights and the heating. The speaker is always listening for its "wake word", after which it records the request and sends it to the company's cloud servers to be processed.</p>`,
a:[{q:"Identify two input devices or sensors in a smart speaker.",m:2,ms:["Microphone(s)","touch/buttons","light sensor","motion/proximity sensor","temperature sensor","camera (some models)"],note:"Award [1] for each up to [2]."},
   {q:"Identify two uses of natural language processing (NLP) in the voice assistant.",m:2,ms:["Converting speech to text (speech recognition)","understanding the meaning/intent of the request","generating a spoken reply (text to speech)","translating between languages","recognising different users' voices"],note:"Award [1] for each use up to [2]."},
   {q:"Describe the role of the cloud servers in processing a request.",m:2,ms:["The recorded audio is sent over the internet to powerful servers","which analyse the speech using AI and send back the response/command to the speaker or smart device"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one reason why the voice assistant might not understand a family member.",m:2,ms:["The family member has a strong accent/speaks another language/dialect","which was under-represented in the training data","Background noise","interferes with speech recognition","Young children or older people speak differently","so the model is less accurate for them"],note:"Award [1] for a reason and [1] for its development up to [2]."},
   {q:"Explain two privacy risks of having a voice assistant in the home.",m:4,ms:["Accidental activation","private conversations may be recorded and sent to the cloud","Recordings stored by the company","could be reviewed by staff, hacked or shared with third parties","Profiling","data about routines and preferences used for targeted advertising","Linked smart devices","could reveal when the home is empty, helping burglars"],note:"Award [1] for each risk and [1] for its development. Mark as [2] + [2]."}],
c:{q:"To what extent do the benefits of voice assistants in the home outweigh the concerns?",
ind:["Benefits: convenience and hands-free control (systems)","accessibility for people with visual or mobility impairments, older people (values)","energy savings from smart heating/lighting control","entertainment and information on demand","Concerns: privacy and surveillance in a private space (space, power)","data used for advertising/profiling; corporate control of data (power)","security vulnerabilities of connected devices","dependence on internet and on one company's ecosystem","children's interactions and data","a reasoned conclusion, e.g. benefits outweigh concerns if privacy settings are used"],
kw:"Identity, power, space, systems, values and ethics, AI, NLP, IoT, privacy, surveillance, accessibility."}},

{id:"digital-wallet",title:"Digital wallets in a street market",t:["3.4","3.1"],x:["4.2","4.7"],
stem:`<p>Traders at a large street market have started accepting payments through a mobile digital wallet. Customers scan the trader's QR code with their phone, enter the amount and confirm the payment with a PIN or fingerprint. The money arrives in the trader's account within seconds.</p><p>Some older customers and traders still prefer to use cash.</p>`,
a:[{q:"Identify two benefits for traders of accepting digital wallet payments.",m:2,ms:["No need to handle/carry cash (safer)","payment received instantly","no need to give change","automatic record of sales","reach customers who do not carry cash","reduced risk of counterfeit notes"],note:"Award [1] for each up to [2]."},
   {q:"Identify two methods of authentication used to confirm a payment.",m:2,ms:["PIN","fingerprint/biometric","face recognition","password","one-time code (two-factor authentication)"],note:"Award [1] for each up to [2]. Accept those in the stem."},
   {q:"Describe how encryption protects payment data.",m:2,ms:["Payment data is converted into an unreadable form (ciphertext) using a key before it is sent","so if it is intercepted it cannot be understood; only the intended receiver with the correct key can decrypt it"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one reason why some older customers may prefer to use cash.",m:2,ms:["Lack of confidence/skills with smartphones","so they worry about making mistakes","Do not own a smartphone/data plan","so they cannot use the wallet","Cash makes it easier to control/see spending","and they distrust digital systems/fear fraud"],note:"Award [1] for a reason and [1] for its development up to [2]."},
   {q:"Explain two risks for traders who rely only on digital wallet payments.",m:4,ms:["Network or system outages","mean no sales can be made","Transaction fees","reduce traders' profits","Fraud/scams (fake payment screens)","traders may hand over goods without being paid","Excluding customers without phones","losing sales","Data about sales visible to the company/tax authorities","raising privacy concerns"],note:"Award [1] for each risk and [1] for its development. Mark as [2] + [2]."}],
c:{q:"Discuss whether governments should encourage a move to a cashless society.",
ind:["For: reduces crime linked to cash (robbery, money laundering, tax evasion) (power)","faster, cheaper transactions; supports e-commerce (change, systems)","financial inclusion for people without bank branches nearby","data helps understand the economy","Against: excludes people without phones, skills or connectivity (digital divide, values)","loss of privacy — every purchase is recorded (surveillance, power)","vulnerable to outages and cyberattacks","dependence on private payment companies and their fees","cultural importance of cash for some communities","a reasoned conclusion, e.g. support digital payments while keeping cash available"],
kw:"Change, power, systems, values and ethics, digital divide, inclusion, privacy, encryption, authentication."}},

{id:"museum-vr",title:"Virtual museum of cultural heritage",t:["3.5","3.1"],x:["4.1"],
stem:`<p>A national museum has used 3D scanning to create digital copies of fragile historical objects. Visitors anywhere in the world can now explore a virtual reality (VR) version of the museum using a headset, or a 3D version in a web browser.</p><p>Some of the objects come from communities in other countries, who have asked for them to be returned.</p>`,
a:[{q:"Identify two items of hardware needed to experience the VR museum.",m:2,ms:["VR headset","computer/smartphone/games console","motion controllers","headphones","internet connection/router","sensors/base stations"],note:"Award [1] for each up to [2]."},
   {q:"Identify two characteristics of immersive digital media.",m:2,ms:["Interactive","user feels present in a virtual environment","3D/360° view","responds to user movement (head tracking)","multisensory (sound, haptics)","non-linear exploration"],note:"Award [1] for each up to [2]."},
   {q:"Describe the difference between virtual reality (VR) and augmented reality (AR).",m:2,ms:["VR replaces the real world with a fully computer-generated environment","AR overlays digital content onto the user's view of the real world"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one benefit of digital preservation for fragile historical objects.",m:2,ms:["Objects can be studied/viewed without being handled","so they are protected from damage","A permanent digital record exists","if the original is damaged/destroyed (fire, conflict)"],note:"Award [1] for a benefit and [1] for its development up to [2]."},
   {q:"Explain two challenges of keeping the virtual museum available for the future.",m:4,ms:["File formats and software become obsolete","so files may not open in future (media obsolescence)","Hardware changes (headsets)","so the experience must be rebuilt for new devices","Large storage needs","high ongoing cost of servers and backups","Funding and maintenance","staff needed to update and secure the platform"],note:"Award [1] for each challenge and [1] for its development. Mark as [2] + [2]."}],
c:{q:"To what extent can virtual museums replace the return of cultural objects to their communities of origin?",
ind:["Virtual access widens access globally, including for the communities of origin (space, change)","digital copies preserve and share heritage (values)","Counter: communities' rights to own and use their heritage; the physical object has cultural/spiritual meaning (identity, values)","who controls/owns the digital copies and earns income from them (power)","digital access needs devices and connectivity (digital divide)","virtual experience is not the same as authentic presence","possible combined approach: return objects and share digital copies","a reasoned conclusion"],
kw:"Change, identity, power, space, values and ethics, immersive media, digital preservation, ownership, cultural heritage."}},

{id:"esports",title:"Esports and live streaming",t:["3.5","3.4"],x:["4.1","4.2"],
stem:`<p>A 17-year-old gamer live streams her esports matches every evening. She earns money from viewers' donations, subscriptions and sponsorship from a gaming chair company. Her streams regularly have more than 5000 viewers.</p>`,
a:[{q:"Identify two items of hardware the gamer needs to live stream.",m:2,ms:["Computer/console","webcam/camera","microphone","capture card","high-speed internet connection/router","headset","lighting"],note:"Award [1] for each up to [2]."},
   {q:"Identify two ways in which viewers can interact during a live stream.",m:2,ms:["Live chat/comments","donations/tips","emotes/reactions","polls","subscribing/following","sharing/clipping the stream"],note:"Award [1] for each up to [2]."},
   {q:"Describe why live streaming requires high bandwidth.",m:2,ms:["Video is a large amount of data sent continuously in real time","so the upload speed must be high enough to avoid buffering/lag/low quality"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one reason why the gaming chair company sponsors the gamer.",m:2,ms:["She has a large, targeted audience of gamers","so the product is advertised directly to potential customers","Viewers trust/identify with her (influencer marketing)","so they are more likely to buy"],note:"Award [1] for a reason and [1] for its development up to [2]."},
   {q:"Explain two risks the gamer may face from live streaming.",m:4,ms:["Online harassment/trolling","which can affect her mental health","Doxxing/privacy — revealing her location","putting her physical safety at risk","Unstable income","depends on viewers and platform rules","Long hours/burnout","affecting her health and schoolwork"],note:"Award [1] for each risk and [1] for its development. Mark as [2] + [2]."}],
c:{q:"Evaluate the impact of esports and live streaming on young people.",
ind:["Positive: new careers and income opportunities (change)","community and belonging, identity, creativity and expression (expression, identity)","skills: teamwork, strategy, communication, technical skills","recognised as competitive sport; scholarships","Negative: gaming addiction, screen time, sleep (health)","harassment and toxic communities, especially for girls (values)","exposure of minors online; privacy","pressure and unstable income; few succeed","sponsorship and gambling-style mechanics targeting youth (power)","a reasoned conclusion"],
kw:"Change, expression, identity, power, values and ethics, media, live streaming, influencer, harassment, well-being."}},

{id:"care-robot",title:"Social robots in elder care",t:["3.7","3.6"],x:["4.4","4.7"],
stem:`<p>A care home has introduced small social robots for its elderly residents. The robots remind residents to take medication, play memory games, make video calls to family and alert staff if a resident falls.</p><p>The robot has a friendly face on a screen and can recognise each resident's voice.</p>`,
a:[{q:"Identify two sensors the robot could use to detect that a resident has fallen.",m:2,ms:["Camera","motion sensor","accelerometer/gyroscope (in a worn device)","infrared/heat sensor","microphone (sound of fall/call for help)","pressure sensor","lidar/proximity sensor"],note:"Award [1] for each up to [2]."},
   {q:"Identify two characteristics of a social robot.",m:2,ms:["Interacts with humans socially/conversation","recognises faces/voices/emotions","has human-like or animal-like features (anthropomorphism)","responds to people's behaviour","some autonomy","companionship role"],note:"Award [1] for each up to [2]."},
   {q:"Describe what is meant by the \"uncanny valley\".",m:2,ms:["As robots look more human-like, people feel more comfortable with them up to a point","but when they look almost — but not quite — human, people feel unease/discomfort"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one reason why the designers gave the robot a simple cartoon-like face rather than a realistic human face.",m:2,ms:["To avoid the uncanny valley","so residents feel comfortable/not frightened","A simple face shows clear expressions","which is easier for residents with poor eyesight/dementia to understand"],note:"Award [1] for a reason and [1] for its development up to [2]."},
   {q:"Explain two ways in which the robot could improve the well-being of residents.",m:4,ms:["Video calls with family","reduce loneliness/isolation","Memory games","keep residents mentally active","Medication reminders","help residents stay healthy and independent","Fall alerts","mean help arrives quickly"],note:"Award [1] for each way and [1] for its development. Mark as [2] + [2]."}],
c:{q:"Discuss whether social robots should be used to care for elderly people.",
ind:["For: address staff shortages and ageing populations (change, systems)","24-hour monitoring and fast response to emergencies","companionship and reduced loneliness","supports independence and dignity","Against: cannot replace human empathy and touch; risk of reducing human contact (values)","deception — residents with dementia may believe the robot cares about them (ethics)","privacy of constant monitoring in residents' rooms (space, power)","cost; maintenance; reliability and accountability if it fails","consent of residents with reduced capacity","a reasoned conclusion, e.g. robots as support, not replacement"],
kw:"Change, identity, power, space, systems, values and ethics, social robots, anthropomorphism, uncanny valley, surveillance."}},

{id:"ransomware-council",title:"Ransomware attack on a city council",t:["3.4","3.1"],x:["4.6"],
stem:`<p>A city council's computer systems were hit by a ransomware attack. Residents could not pay local taxes online, register births or book rubbish collections for two weeks. The attackers demanded payment in cryptocurrency to unlock the files.</p><p>The attack began when an employee opened a link in an email that appeared to come from the council's IT department.</p>`,
a:[{q:"Identify two characteristics of ransomware.",m:2,ms:["Malicious software/malware","encrypts files so they cannot be used","demands a ransom/payment to unlock","often spread by email/phishing","may threaten to publish stolen data","often demands cryptocurrency"],note:"Award [1] for each up to [2]."},
   {q:"Identify two characteristics of cryptocurrency that make it attractive to criminals.",m:2,ms:["Anonymity/pseudonymity","no central authority/bank","hard to trace/reverse","cross-border/fast transfers","digital"],note:"Award [1] for each up to [2]."},
   {q:"Describe how this attack is an example of social engineering.",m:2,ms:["The attackers tricked/manipulated the employee by pretending to be a trusted source (IT department)","into clicking the link, rather than hacking the technical system directly"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one reason why the council might decide not to pay the ransom.",m:2,ms:["There is no guarantee the files will be unlocked","so the money may be lost","Paying encourages further attacks/funds crime","and may be illegal/against government policy","Backups may allow recovery","so paying is unnecessary"],note:"Award [1] for a reason and [1] for its development up to [2]."},
   {q:"Explain two measures the council could take to reduce the risk of future attacks.",m:4,ms:["Staff training on phishing","so employees recognise suspicious emails","Regular offline backups","so data can be restored without paying","Keep software updated/patched","closing vulnerabilities","Email filtering and antivirus","to block malicious links/attachments","Multi-factor authentication and limiting access rights","so one compromised account cannot spread the attack"],note:"Award [1] for each measure and [1] for its development. Mark as [2] + [2]."}],
c:{q:"To what extent should local governments move their public services online?",
ind:["For: convenience, 24/7 access, faster services for residents (change, systems)","lower costs and less paperwork","data helps improve services","accessibility for people who cannot travel to offices","Against: cyberattacks can stop essential services (as in the stem)","excludes residents without devices, skills or connectivity (digital divide, values)","privacy and security of sensitive personal data (power)","dependence on IT suppliers; cost of security","Need for offline alternatives and resilience planning","a reasoned conclusion"],
kw:"Change, power, systems, values and ethics, cybercrime, ransomware, social engineering, e-government, digital divide."}},

{id:"chatbot-bank",title:"AI chatbots in customer service",t:["3.6","3.2"],x:["4.2"],
stem:`<p>A bank has replaced most of its telephone customer service staff with an AI chatbot. The chatbot answers questions 24 hours a day in eight languages. Customers who want to speak to a human must ask the chatbot to transfer them, which can involve a long wait.</p>`,
a:[{q:"Identify two types of machine learning.",m:2,ms:["Supervised learning","unsupervised learning","reinforcement learning","deep learning"],note:"Award [1] for each up to [2]."},
   {q:"Identify two tasks the chatbot could carry out for customers.",m:2,ms:["Check account balance","answer frequently asked questions","report a lost card","explain fees/products","book appointments","reset passwords","translate"],note:"Award [1] for each up to [2]."},
   {q:"Describe the difference between narrow (weak) AI and general (strong) AI.",m:2,ms:["Narrow AI performs a specific task or set of tasks (e.g. the chatbot)","general AI would be able to understand and perform any intellectual task a human can"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one advantage for customers of using the chatbot.",m:2,ms:["Available 24/7","so customers get help at any time without waiting for office hours","Supports many languages","so more customers can use the service in their own language","Instant answers","no queue for simple questions"],note:"Award [1] for an advantage and [1] for its development up to [2]."},
   {q:"Explain two impacts on the bank's employees of introducing the chatbot.",m:4,ms:["Job losses/displacement","for telephone staff whose tasks are automated","Remaining staff handle only complex/angry cases","increasing stress","New jobs","in AI training, monitoring and maintenance","Need for retraining/new skills","to work alongside the AI"],note:"Award [1] for each impact and [1] for its development. Mark as [2] + [2]."}],
c:{q:"Evaluate the decision to replace human customer service staff with AI chatbots.",
ind:["Benefits: lower costs, 24/7 service, consistent answers, multilingual (systems, change)","handles large volumes quickly","Drawbacks: frustrating for complex or emotional problems; lack of empathy (values)","excludes customers with low digital skills or disabilities (digital divide)","errors/hallucinations and accountability for wrong advice (ethics)","job losses and effects on communities (power)","privacy of conversation data","trust in the bank may fall","a reasoned conclusion, e.g. hybrid model with easy access to humans"],
kw:"Change, power, systems, values and ethics, AI, NLP, automation, displacement, accountability, accessibility."}},

{id:"telemedicine",title:"Telemedicine in rural areas",t:["3.4","3.3"],x:["4.4"],
stem:`<p>A health authority has set up video consultations so patients in remote villages can see a doctor without travelling to the city. A community health worker in each village helps patients use a tablet and measures their blood pressure with a connected device.</p>`,
a:[{q:"Identify two items of hardware needed for a video consultation.",m:2,ms:["Tablet/computer/smartphone","webcam/camera","microphone","speakers/headphones","router/modem","connected medical device (blood pressure monitor)"],note:"Award [1] for each up to [2]."},
   {q:"Identify two network services used in telemedicine.",m:2,ms:["Video conferencing","VOIP","messaging/chat","email","file sharing (test results, images)","cloud storage of records"],note:"Award [1] for each up to [2]."},
   {q:"Describe one reason why bandwidth is important for a video consultation.",m:2,ms:["Video needs a large amount of data to be transmitted continuously","low bandwidth causes poor image/sound quality or dropped calls, so the doctor may not see symptoms clearly"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one advantage for patients of video consultations.",m:2,ms:["No need to travel long distances","saving time and money/reducing missed work","Faster access to a doctor","so illnesses are treated earlier","Can stay at home when ill","reducing spread of infection"],note:"Award [1] for an advantage and [1] for its development up to [2]."},
   {q:"Explain two limitations of video consultations compared with seeing a doctor in person.",m:4,ms:["The doctor cannot physically examine the patient","so some conditions may be missed","Poor connectivity","interrupts consultations","Privacy","others may overhear in shared spaces/data could be intercepted","Some patients lack digital skills or trust","reducing effectiveness"],note:"Award [1] for each limitation and [1] for its development. Mark as [2] + [2]."}],
c:{q:"To what extent can telemedicine reduce inequalities in access to healthcare?",
ind:["Reduces geographical barriers for rural patients (space, change)","lower costs; access to specialists otherwise unavailable","community health workers help bridge digital skills gaps","Limitations: needs reliable connectivity, electricity and devices (digital divide)","cannot replace physical examinations, tests, surgery","language, literacy and trust issues (values)","privacy and security of health data (power)","may benefit already-connected groups most, widening inequality","depends on investment and policy","a reasoned conclusion"],
kw:"Change, power, space, systems, values and ethics, networks, bandwidth, digital divide, health care, access."}},

{id:"e-voting",title:"Online voting in elections",t:["3.1","3.4"],x:["4.6"],
stem:`<p>A country is considering allowing citizens to vote online in national elections. Voters would log in with a digital ID card and a PIN, cast their vote on a website and receive a code to check that their vote was recorded.</p><p>Supporters say online voting would increase the number of people who vote, especially young people and citizens living abroad.</p>`,
a:[{q:"Identify two methods of authentication that could be used to identify a voter.",m:2,ms:["Digital ID card","PIN/password","biometric (fingerprint/face)","one-time code sent to phone (2FA)","security questions"],note:"Award [1] for each up to [2]."},
   {q:"Identify two characteristics of blockchain.",m:2,ms:["Decentralised/distributed ledger","records cannot easily be changed (immutable)","transparent/verifiable","uses cryptography/hashing","blocks linked in a chain","no central authority"],note:"Award [1] for each up to [2]."},
   {q:"Describe how a denial of service (DoS) attack could disrupt online voting.",m:2,ms:["The voting website is flooded with huge numbers of requests","so it becomes slow or unavailable and genuine voters cannot cast their votes"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one reason why online voting might increase the number of people who vote.",m:2,ms:["Voting is more convenient — from home/any time during the voting period","so people who are busy, ill or abroad can still vote","Young people are used to doing things online","so they are more likely to take part"],note:"Award [1] for a reason and [1] for its development up to [2]."},
   {q:"Explain two threats to the integrity of an online election.",m:4,ms:["Hacking of servers","votes could be changed/deleted","Coercion/vote buying","someone may watch or pressure the voter at home","Identity fraud/stolen credentials","someone could vote on behalf of another person","Malware on voters' devices","could alter votes before they are sent","Lack of verifiability/trust","citizens may not accept the result"],note:"Award [1] for each threat and [1] for its development. Mark as [2] + [2]."}],
c:{q:"Discuss whether the benefits of online voting outweigh the risks.",
ind:["Benefits: higher participation, accessibility for disabled voters and citizens abroad (values, change)","faster, cheaper counting; fewer human errors","verification codes may increase transparency","Risks: cyberattacks, foreign interference (power)","secrecy of the ballot and coercion at home (ethics)","digital divide — some groups excluded","loss of public trust if results cannot be independently audited","technical failure during election","examples of countries that use or abandoned e-voting","a reasoned conclusion"],
kw:"Change, power, systems, values and ethics, authentication, blockchain, security, democracy, trust."}},

{id:"fact-check",title:"Misinformation on messaging apps",t:["3.5","3.4"],x:["4.6","4.7"],
stem:`<p>False health rumours spread quickly in family and community groups on an encrypted messaging app. Because messages are end-to-end encrypted, the app cannot read them. The app has limited how many groups a message can be forwarded to at once and labels messages that have been forwarded many times.</p>`,
a:[{q:"Identify two reasons why people share false information online.",m:2,ms:["They believe it is true","it comes from someone they trust (family/friends)","it is emotional/shocking","to warn others/help","political or financial motives","it confirms existing beliefs"],note:"Award [1] for each up to [2]."},
   {q:"Identify two characteristics of digital media that allow rumours to spread quickly.",m:2,ms:["Rapid sharing/forwarding","reaches many people at once/one-to-many","easy to copy/remix","available on mobile devices anywhere","convergence of text, image, video","hard to trace the original source"],note:"Award [1] for each up to [2]."},
   {q:"Describe what is meant by end-to-end encryption.",m:2,ms:["Messages are encrypted on the sender's device and only decrypted on the receiver's device","so no one in between, including the app company, can read them"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one way in which labelling messages as \"forwarded many times\" may reduce the spread of misinformation.",m:2,ms:["It warns users the message did not come from the sender personally","so they may think twice/check before believing or sharing it"],note:"Award [1] for a way and [1] for its development up to [2]."},
   {q:"Explain two ways in which users could check whether a message is reliable.",m:4,ms:["Check the original source","e.g. official health authority website","Use a fact-checking website/service","which investigates viral claims","Reverse image search","to see if a photo is old/out of context","Compare with several reliable news sources","to see if the claim is reported"],note:"Award [1] for each way and [1] for its development. Mark as [2] + [2]."}],
c:{q:"To what extent should messaging apps be responsible for stopping the spread of misinformation on their platforms?",
ind:["Responsible: their design (forwarding, groups) enables rapid spread (power, systems)","they can add friction, labels, links to reliable information","misinformation can cause real harm (health, violence)","Limits: end-to-end encryption protects privacy and free expression; scanning messages would weaken it (expression, values)","users and communities also responsible; media literacy education","governments may use 'misinformation' laws to censor (power)","difficult to define truth at scale; risk of errors","a reasoned conclusion"],
kw:"Change, expression, power, systems, values and ethics, misinformation, encryption, censorship, media literacy."}},

{id:"delivery-robots",title:"Autonomous delivery robots",t:["3.7","3.6"],x:["4.3","4.2"],
stem:`<p>A supermarket is trialling small six-wheeled robots that deliver groceries along pavements to customers' homes within 3 km. The robots navigate using cameras, ultrasonic sensors and maps, and a human operator can take control remotely if a robot gets stuck.</p>`,
a:[{q:"Identify two sensors used by the delivery robot.",m:2,ms:["Camera","ultrasonic sensor","GPS","lidar/radar","infrared","accelerometer/gyroscope","microphone"],note:"Award [1] for each up to [2]. Accept those in the stem."},
   {q:"Identify two characteristics of an autonomous technology.",m:2,ms:["Senses its environment","makes decisions without human input","acts/moves in the physical world","uses machine vision/learning","some degree of independence/autonomy","can adapt to changing conditions"],note:"Award [1] for each up to [2]."},
   {q:"Describe the role of the human operator in this system.",m:2,ms:["Monitors the robots remotely and takes control when the robot cannot decide (e.g. blocked path)","so the robot can continue safely; a 'human in the loop'"],note:"Award [1] for each part up to [2]."}],
b:[{q:"Explain one environmental benefit of using delivery robots instead of delivery vans.",m:2,ms:["Robots are electric and small","so they produce fewer emissions/use less energy than vans","Fewer vans on roads","reducing congestion and air pollution"],note:"Award [1] for a benefit and [1] for its development up to [2]."},
   {q:"Explain two challenges of using delivery robots on public pavements.",m:4,ms:["Obstructing pedestrians","especially wheelchair users and people with prams","Vandalism/theft","robots or groceries could be stolen","Complex environments","kerbs, crowds, weather may confuse sensors","Unclear laws","about liability if a robot causes an accident"],note:"Award [1] for each challenge and [1] for its development. Mark as [2] + [2]."}],
c:{q:"Evaluate the use of autonomous delivery robots in towns and cities.",
ind:["Opportunities: lower delivery costs; 24-hour service (systems)","reduced emissions and traffic (environmental)","helps people who cannot easily shop (elderly, disabled)","Challenges: sharing public space; accessibility of pavements (space, values)","job losses for delivery drivers (power, change)","privacy — robots constantly record streets with cameras","safety, liability and regulation","limited range/capacity; weather","a reasoned conclusion"],
kw:"Change, power, space, systems, values and ethics, autonomous technologies, sensors, displacement, regulation."}}
];

/* HL Paper 1 Section B — extended response [12] on the HL extension challenge topics. */
const HLB=[
{id:"hb-platform-union",ch:"5.1",title:"Digital organizing for platform workers",stem:`<p>Ride-hailing drivers in a large city have created an online network and app to share information about pay, safety and working conditions. Drivers use the app to compare their earnings, report unsafe passengers and organize collective action, such as switching off the ride-hailing app at the same time to demand higher pay.</p>`,
claim:"It is claimed that digital networks give platform workers real power to improve their working conditions.",
ind:{"Supporting the claim":["Connects isolated workers who never meet in a workplace; shared data reveals unfair pay (power, systems)","coordinated action (log-offs) can pressure platforms","evidence gathered can support legal cases and lobbying","low cost, fast and scalable organizing"],"Counter-claims":["Platforms control the algorithms and can deactivate drivers (power imbalance)","drivers are classed as self-employed and may lack legal right to unionize","participation may be low; drivers fear retaliation","networks can be monitored by the company; privacy risks","lasting change may need laws/regulation rather than apps"]},
kw:"Future of work, power, systems, values and ethics, gig economy, collective action, algorithmic management."},
{id:"hb-ai-hiring",ch:"5.1",title:"AI in recruitment",stem:`<p>A multinational company uses an AI system to screen job applications. The system analyses CVs and short recorded video interviews, scoring candidates on skills, word choice and facial expressions. Only the highest-scoring 10% are interviewed by a human.</p>`,
claim:"It is claimed that AI recruitment systems make hiring fairer.",
ind:{"Supporting the claim":["Consistent criteria applied to every applicant; removes some individual human biases","can process thousands of applications, giving more people a chance","can be designed to ignore names, gender, age","audits can measure and reduce bias"],"Counter-claims":["Trained on past hiring data, which may encode discrimination (algorithmic bias)","facial expression analysis lacks scientific validity; disadvantages neurodivergent or disabled candidates","black-box decisions; candidates cannot challenge results (accountability)","may disadvantage non-native speakers or candidates with poor internet/cameras","regulation (e.g. requirements for audits and human review) is uneven"]},
kw:"Future of work, values and ethics, power, algorithmic bias, transparency, accountability, discrimination."},
{id:"hb-telehealth-refugees",ch:"5.1",title:"Mobile health for refugees",stem:`<p>An NGO has developed a mobile app for refugees living in camps. The app provides health information in several languages, allows users to book appointments with volunteer doctors through video calls, and stores a digital health record that the refugee can keep if they move to another country.</p>`,
claim:"It is claimed that mobile health apps can significantly improve access to healthcare for refugees.",
ind:{"Supporting the claim":["Many refugees own mobile phones; information in own language","portable digital record follows the person across borders (space)","video consultations overcome shortages of local doctors","reduces need to travel within/out of camps"],"Counter-claims":["Limited connectivity, charging and data costs in camps (digital divide)","privacy and safety — data could be accessed by authorities or persecutors (power)","literacy, trust and cultural barriers","cannot provide medicines, tests or treatment","dependent on NGO funding; sustainability","consent and data ownership of vulnerable people"]},
kw:"Global well-being, access to health care, migration, space, power, values and ethics, privacy, inequality."},
{id:"hb-hate-speech",ch:"5.2",title:"Automated moderation of hate speech",stem:`<p>A social media platform uses an AI system to automatically detect and remove posts that contain hate speech. The system removes millions of posts a month. Some users complain that their posts were removed wrongly, especially posts written in minority languages or that discuss discrimination they have experienced.</p>`,
claim:"It is claimed that automated content moderation is an effective way to protect users from hate speech.",
ind:{"Supporting the claim":["Scale: only automation can review billions of posts quickly","removes harmful content before many users see it","protects targeted groups and supports participation (values)","consistent rules; reduces trauma for human moderators"],"Counter-claims":["AI struggles with context, sarcasm, reclaimed words and minority languages (bias)","over-removal silences the very groups it aims to protect (expression, power)","under-removal of coded hate speech","lack of transparency and appeal processes (accountability)","platform decides what counts as hate speech; differing laws across countries","human moderation still needed"]},
kw:"Governance and human rights, diversity and discrimination, expression, power, values and ethics, AI, content filters, censorship."},
{id:"hb-e-petition",ch:"5.2",title:"Online petitions and participation",stem:`<p>A national parliament runs an official e-petition website. Any citizen can start a petition. If a petition reaches 100 000 signatures within six months, it must be considered for debate in parliament. Signatures are verified by email and postcode.</p>`,
claim:"It is claimed that e-petition websites increase citizens' influence on government decisions.",
ind:{"Supporting the claim":["Low barrier to participation; anyone can raise an issue (participation and representation)","guaranteed consideration for debate at a threshold","social media sharing spreads awareness quickly","gives government data on public concerns"],"Counter-claims":["Debate does not mean the law will change; few petitions lead to action ('slacktivism')","favours groups with large online networks; digital divide excludes some citizens","verification by email/postcode can be manipulated (bots, fake accounts)","government controls the platform and agenda (power)","may distract from other forms of participation"]},
kw:"Governance and human rights, participation and representation, power, systems, values and ethics, e-democracy."},
{id:"hb-predictive-policing",ch:"5.2",title:"Predictive policing",stem:`<p>A city police force uses software that analyses past crime data to predict where crimes are most likely to happen. Officers are sent to patrol the "hot spots" identified by the software each day.</p>`,
claim:"It is claimed that predictive policing makes communities safer without discriminating against particular groups.",
ind:{"Supporting the claim":["Efficient use of limited police resources","data-driven rather than based on individual officers' assumptions","may deter crime in high-risk areas","results can be monitored and audited"],"Counter-claims":["Past data reflects past policing patterns, so over-policed (often minority/poor) areas are targeted again — feedback loop (bias)","more patrols lead to more recorded crime in those areas, reinforcing predictions","lack of transparency in proprietary algorithms (accountability)","erodes trust between police and communities (power, values)","displacement of crime rather than reduction","need for independent oversight and community involvement"]},
kw:"Governance and human rights, discrimination, security, power, values and ethics, algorithmic bias, accountability."},
{id:"hb-deforestation",ch:"5.3",title:"Satellite monitoring of deforestation",stem:`<p>An environmental organization uses satellite images and machine learning to detect illegal tree cutting in rainforests almost in real time. Alerts are sent to local rangers and published on a public map so that journalists and citizens can see where deforestation is happening.</p>`,
claim:"It is claimed that real-time digital monitoring is an effective way to reduce deforestation.",
ind:{"Supporting the claim":["Covers huge, remote areas that rangers cannot patrol","fast alerts allow action before large areas are lost","public map increases transparency and pressure on governments/companies (power)","data supports evidence for prosecutions and policy"],"Counter-claims":["Detection does not guarantee enforcement; rangers may lack resources or face corruption/danger","cloud cover and accuracy limits; false positives","illegal loggers adapt (small-scale clearing)","does not address economic causes (poverty, demand for land/products)","energy and costs of the digital system","indigenous communities' involvement and data sovereignty"]},
kw:"Sustainable development, climate change and action, systems, power, values and ethics, big data, AI, monitoring."},
{id:"hb-traffic",ch:"5.3",title:"Smart traffic management",stem:`<p>A city has installed sensors and cameras at junctions. An AI system adjusts traffic lights in real time to reduce queues, gives priority to buses and emergency vehicles, and publishes live traffic data on an app so drivers can choose quieter routes.</p>`,
claim:"It is claimed that smart traffic systems will significantly reduce a city's carbon emissions.",
ind:{"Supporting the claim":["Less idling and stop–start driving reduces fuel use and emissions","bus priority makes public transport faster and more attractive","data helps planners redesign roads and cycle routes","real-time information spreads traffic more evenly"],"Counter-claims":["Smoother traffic may encourage more car use (induced demand), increasing emissions","emissions from manufacturing/running sensors and data centres","benefits small compared with switching to electric vehicles/public transport","surveillance concerns from cameras (privacy)","costly; may benefit wealthier districts first","need for wider policies (congestion charges, cycling infrastructure)"]},
kw:"Sustainable development, responsible use of resources, climate action, systems, change, space, IoT, AI."},
{id:"hb-ewaste",ch:"5.3",title:"Digital product passports and e-waste",stem:`<p>A group of countries plans to require every new smartphone and laptop to have a "digital product passport" — a QR code linked to an online record of the materials used, how to repair the device, and where to recycle it.</p>`,
claim:"It is claimed that digital product passports will significantly reduce electronic waste.",
ind:{"Supporting the claim":["Repair information extends device lifespans (responsible consumption)","material data helps recyclers recover valuable metals","transparency puts pressure on manufacturers to design for repair (power)","consumers can make informed choices"],"Counter-claims":["Information alone does not change consumer behaviour or planned obsolescence","manufacturers may restrict parts/software for repair","e-waste exported to countries with weak recycling systems","cost and complexity of maintaining records; data accuracy","only applies in participating countries","needs right-to-repair laws and recycling infrastructure"]},
kw:"Sustainable development, managing pollution and waste, systems, power, values and ethics, e-waste, right to repair."}
];
